import React from "react";

/**
 * Registro de iconos de marca.
 *
 * Existe porque lucide-react no incluye logos de marca: el sitio los resolvía
 * con glifos genéricos (`Facebook`, `Linkedin`), SVG pegados dentro de tres
 * componentes distintos (X, TikTok, WhatsApp) y metáforas para las tecnologías
 * (`Globe` para Next.js, `Server` para Laravel). Cuatro fuentes para el mismo
 * problema.
 *
 * Reglas del registro:
 * - Todo se dibuja en un lienzo 24x24 y hereda el color con `currentColor`.
 * - `title` es el nombre humano de la marca; `<BrandIcon>` decide si emitirlo
 *   como `<title>` accesible o marcar el icono como decorativo.
 * - `hex` es el color oficial de la marca, para los estados que lo pidan.
 *
 * PROCEDENCIA DE LOS TRAZADOS. La mayoría viene de Simple Icons, publicado bajo
 * CC0 1.0 (dominio público). Se trajeron de su fuente en vez de redibujarse a
 * mano tras comprobar que la aproximación manual no era fiable: de 23 marcas
 * dibujadas de memoria solo 2 coincidían con el trazado real, y el elefante de
 * PostgreSQL salía como un pulpo.
 *
 * Las dos excepciones —LinkedIn y Amazon Web Services— llevan trazado propio y
 * están marcadas con un comentario: no figuran en el índice de Simple Icons
 * porque sus titulares pidieron retirarlas, así que no se toman de ahí.
 *
 * MySQL viene de Devicon (MIT), porque su logo en Simple Icons incluye el
 * wordmark y no sobrevive al tamaño de icono.
 *
 * Las marcas pertenecen a sus titulares; aquí se usan para identificar la
 * tecnología o la red, que es uso nominativo.
 *
 * lucide sigue siendo el proveedor para iconografía conceptual (flechas,
 * calendario, candado). Aquí solo viven marcas.
 */

export interface BrandIconDefinition {
  /** Nombre humano de la marca, usado en `<title>` y `aria-label`. */
  title: string;
  /** Contenido del lienzo 24x24. */
  content: React.ReactNode;
  /** Color oficial de marca, para usos que lo pidan explícitamente. */
  hex?: string;
  /** Lienzo propio, cuando el trazado no viene en la rejilla 24x24. */
  viewBox?: string;
}

